package com.quincaisoft.platformcontrol.security;import org.springframework.context.annotation.*;import org.springframework.core.annotation.Order;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.core.*;
@Configuration @ConditionalOnProperty(name="quincai.platform.enabled",havingValue="true") public class PlatformSecurity{
@Bean @Order(1) SecurityFilterChain platformChain(HttpSecurity http,@Value("${quincai.platform.issuer}")String issuer,@Value("${quincai.platform.audience}")String audience,@Value("${spring.security.oauth2.resourceserver.jwt.issuer-uri}")String merchantIssuer,@Value("${quincai.security.audience}")String merchantAudience)throws Exception{
 if(issuer.equals(merchantIssuer)||audience.equals(merchantAudience))throw new IllegalStateException("Control plane requires separate issuer and audience");NimbusJwtDecoder decoder=JwtDecoders.fromIssuerLocation(issuer);OAuth2TokenValidator<Jwt> aud=jwt->jwt.getAudience().contains(audience)?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token"));decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer(issuer),aud));return http.securityMatcher("/admin/**").csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.decoder(decoder))).build();}}
